import catalogJson from '@/generated/catalog.json';
import type { Catalog, LearningItem } from '@/domain/types';
import { createCatalogIndex } from '@/lib/catalog-index';

/** Generated by `pnpm generate` (scripts/generate-content.ts) and validated by `pnpm check:content`. */
export const catalog = createCatalogIndex(catalogJson as Catalog);

export const LEVEL_LABELS = { beginner: 'Beginner', intermediate: 'Intermediate', advanced: 'Advanced' } as const;

export function itemLabel(item: LearningItem): string {
  return item.kind === 'lab' ? 'Lab' : (item.label ?? 'Lesson');
}
